    sg.addColorStop(0,'#e9969b');sg.addColorStop(.35,'#f2a1a4');sg.addColorStop(.6,'#ffa6c0');sg.addColorStop(.82,'#ffb08a');sg.addColorStop(1,'#c9875e');x.fillStyle=sg;x.fillRect(0,0,W,H);
