  o.filter='blur(12px)';o.drawImage(shape(20,'rgba(70,20,50,.42)'),5,12);o.filter='none';
  // body: soft-edged, like a tuft of cotton wool
  const body=document.createElement('canvas');body.width=W;body.height=H;const b=body.getContext('2d');
  b.filter='blur(4px)';b.drawImage(shape(20,'#e9e1e6'),0,0);b.filter='none';
  // fluffy edge: little puffs sitting on the outline
