  for(let k=0,placed=0;k<200000&&placed<700;k++){const x=rnd()*W,y=rnd()*H;if(a(x,y)<128)continue;if(a(x+9,y)>128&&a(x-9,y)>128&&a(x,y+9)>128&&a(x,y-9)>128)continue;placed++;
    const r=6+rnd()*8,g=b.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,'rgba(240,233,237,.85)');g.addColorStop(1,'rgba(233,225,230,0)');b.fillStyle=g;b.beginPath();b.arc(x,y,r,0,7);b.fill();}
