  const hd=hx.getImageData(0,0,w,h).data,n=document.createElement('canvas');n.width=w;n.height=h;const nx=n.getContext('2d'),nd=nx.createImageData(w,h),hv=(i,j)=>hd[(Math.min(h-1,Math.max(0,j))*w+Math.min(w-1,Math.max(0,i)))*4]/255;
