function makeSkein(L,R,rho,k,tube,tw,color){
  const g=new THREE.Group(),yt=yarnTex();yt.repeat.set(70,1);
  const mat=new THREE.MeshStandardMaterial({color,map:yt,bumpMap:yt,bumpScale:.04,roughness:1});
  for(let j=0;j<k;j++){const pts=[],phi=j/k*Math.PI*2,rr=rho*(.55+.45*((j*7)%k)/k);
    for(let i=0;i<220;i++){const t=i/220*Math.PI*2,c=Math.cos(t),sn=Math.sin(t);
      const th=tw*Math.PI*c,psi=phi+9*t,y0=R*sn+rr*Math.cos(psi),z0=rr*Math.sin(psi);
      pts.push(new THREE.Vector3(L*c*(1-.04*Math.cos(psi)),y0*Math.cos(th)-z0*Math.sin(th),y0*Math.sin(th)+z0*Math.cos(th)));}
    const m=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts,true),440,tube,6,true),mat);m.castShadow=m.receiveShadow=true;g.add(m);}
  return g;
}
