    if(!u.sparks){u.sparks=[];for(let k=0;k<3;k++){const q={ph:Math.random()*6.28,sp:1.6+Math.random()*2.2,sz:3+Math.random()*2.2,was:0};spot(q);u.sparks.push(q);}}
