  const W=innerWidth,H=innerHeight;x.clearRect(0,0,W,H);if(night)return;   // no light rays at night
  const tone=night?'night':skyName==='sunset'?'sunset':'day',C={day:[255,240,190],sunset:[255,200,160],night:[225,232,255]}[tone],K={day:.14,sunset:.18,night:.12}[tone];
  const lg=document.getElementById('logo'),lr=lg?lg.getBoundingClientRect():{left:20,top:20,width:240,height:70};   // the rays pour out of the pink plume sign
  const ox=lr.left+lr.width*.42,oy=lr.top+lr.height*.42,L=Math.hypot(W,H)*1.5,col=a=>`rgba(${C[0]},${C[1]},${C[2]},${a})`;let r0=7;const rr=()=>{r0=(r0*16807)%2147483647;return r0/2147483647;};
  x.filter='blur(3px)';
