  document.body.appendChild(W);
  stitchText(W.querySelector('.wtitle'),mode==='featured'?'fresh from the cloud':'a little gift',96,.5,4.2,[9,5.5]);stitchIcon2(W.querySelector('.wx canvas'));
  const card=W.querySelector('.wcard');requestAnimationFrame(()=>{paintCloudCard(W.querySelector('.wbg'),card.offsetWidth+80,card.offsetHeight+80);W.classList.add('on');});
  const close=()=>{W.classList.remove('on');setTimeout(()=>W.remove(),450);removeEventListener('keydown',esc);},esc=e=>{if(e.key==='Escape')close();};
  addEventListener('keydown',esc);W.addEventListener('click',e=>{if(e.target===W||e.target.closest('.wx,.wno,a'))close();});
